  1790	/// so that the apprt can reload the configuration.
  1791	fn notifyConfigConditionalState(self: *Surface) void {
  1792	    _ = self.rt_app.performAction(
  1793	        .{ .surface = self },
  1794	        .reload_config,
  1795	        .{ .soft = true },
  1796	    ) catch |err| {
  1797	        log.warn("failed to notify app of config state change err={}", .{err});
  1798	    };
  1799	}
