206	    /// Calculates the amount of blank space around the grid. This is possible
207	    /// when padding isn't balanced.
208	    ///
209	    /// The "self" screen size here should be the unpadded screen.
210	    pub fn blankPadding(self: ScreenSize, padding: Padding, grid: GridSize, cell: CellSize) Padding {
211	        const grid_width = grid.columns * cell.width;
212	        const grid_height = grid.rows * cell.height;
213	        const padded_width = grid_width + (padding.left + padding.right);
214	        const padded_height = grid_height + (padding.top + padding.bottom);
215	
216	        // Note these have to use a saturating subtraction to avoid underflow
217	        // because our padding can cause the padded sizes to be larger than
218	        // our real screen if the screen is shrunk to a minimal size such
219	        // as 1x1.
